from pathlib import Path
import html, json, re, difflib
import markdown
O=Path(__file__).resolve().parent
R=O.parents[3]
NAMES=["Boolean_Verbs","Boolean_Gallery","Boolean_Works"]
LABELS={"Boolean_Verbs":"What belongs to the result","Boolean_Gallery":"The familiar form has neighbours","Boolean_Works":"Room for a body"}
NOTES={"Boolean_Verbs":"The recurring box and sphere lead into membership, the generated cavity surface and operand order. The list of operations gives way to what they let us make.","Boolean_Gallery":"All six families remain. Their arrangement exposes the authority of defaults, the choice to disclose a process and different accounts of what was removed.","Boolean_Works":"The deliberate failed promises remain beside the working burrow. Accommodation and seclusion become part of the inquiry; the rack and workbench remain visibly unfinished."}
def render(s,prefix):
 s=re.sub(r"<!--\s*@([^>]*?)\s*-->",lambda m: '<a id="'+prefix+'-encounter-'+html.escape(m[1].strip(),quote=True)+'"></a>' if m[1].strip() else '',s)
 return markdown.markdown(s,extensions=['extra','sane_lists'])
css="""body{margin:0;background:#f4efe6;color:#302b25;font:19px/1.78 Georgia,serif}main{max-width:1100px;margin:auto;padding:64px 28px}header,.reading{max-width:740px}h1{font-size:clamp(2.5rem,5vw,4.4rem);line-height:1.08;margin:20px 0}h2{font-size:1.8rem;line-height:1.25;margin-top:2.4em}h3{font-size:1.4rem}a{color:#77512e}.eyebrow,nav,summary,.note,footer,.status,.pair h4{font-family:system-ui,sans-serif}.eyebrow{font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:#705945}nav{display:flex;flex-wrap:wrap;gap:12px 24px;padding:20px 0;font-size:15px}section{border-top:1px solid #b9aa97;margin-top:75px;padding-top:25px}article{margin-top:48px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#e9e2d7;padding:18px;font:14px/1.65 ui-monospace,monospace;tab-size:4}code{font-size:.86em}pre code{font-size:inherit}.status,.note{font-size:15px;line-height:1.65;color:#635648}.status{border-left:3px solid #a47b51;padding-left:18px;max-width:850px}details{background:#fff9f0;border:1px solid #d5c6b5;padding:18px;margin-top:28px}summary{cursor:pointer;font-size:16px;font-weight:600}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px;border-top:1px solid #d5c6b5;margin:25px 0;font-size:16px}.pair>div{min-width:0}.pair h4{font-size:13px;text-transform:uppercase;letter-spacing:.08em;color:#6b604f}.pair h2{font-size:1.3rem;margin-top:1em}.reading{scroll-margin-top:30px}footer{font-size:14px;margin-top:65px;border-top:1px solid #b9aa97;padding-top:20px}blockquote{border-left:3px solid #bea789;padding-left:22px;margin-left:0}.empty{font-style:italic;color:#817565}@media(max-width:760px){.pair{grid-template-columns:1fr}main{padding:36px 20px}}"""
parts=[]
for name in NAMES:
 before=(O/(name+'.before.md')).read_text(encoding='utf-8')
 after=(R/'commons/maps'/name/'final.md').read_text(encoding='utf-8')
 assert after==(O/(name+'.after.md')).read_text(encoding='utf-8'),name+' changed; reconcile before rebuilding'
 a=re.split(r'\n\s*\n',before.strip());b=re.split(r'\n\s*\n',after.strip());pairs=[]
 for i,(tag,i1,i2,j1,j2) in enumerate(difflib.SequenceMatcher(a=a,b=b,autojunk=False).get_opcodes()):
  if tag=='equal':continue
  old=render('\n\n'.join(a[i1:i2]),name+'-old-'+str(i)) or '<p class="empty">No passage here.</p>'
  new=render('\n\n'.join(b[j1:j2]),name+'-new-'+str(i)) or '<p class="empty">The following passage now carries this transition.</p>'
  pairs.append('<div class="pair"><div><h4>Before</h4>'+old+'</div><div><h4>Now</h4>'+new+'</div></div>')
 parts.append('<section id="'+name+'"><header><p class="eyebrow">'+name.replace('_',' ')+'</p><h2>'+LABELS[name]+'</h2><p>'+NOTES[name]+'</p><p class="note"><a href="/compose/sources?map='+name+'&amp;doc=final">Read and comment on final.md</a></p></header><details><summary>Compare the complete revision</summary>'+''.join(pairs)+'<p class="note"><a href="'+name+'.diff">Exact diff</a> · <a href="'+name+'.before.md">Full original</a> · <a href="'+name+'.after.md">Current chapter</a></p></details><article class="reading" id="reading-'+name+'">'+render(after,'reading-'+name)+'</article></section>')
nav=''.join('<a href="#reading-'+m+'">'+m.replace('_',' ')+'</a>' for m in NAMES)
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Room for a body — Boolean Surfaces</title><style>'+css+'</style></head><body><main><header><p class="eyebrow">Ada Research · Boolean Surfaces · 24 September 2026</p><h1>Room for a body.</h1><p>A cut can make somewhere to stand. A default can make an alternative hard to imagine. A wall can stop a body and give it somewhere to withdraw.</p><p>The sequence keeps its critical inquiry into the museum’s promises and how its objects are presented. The writing now follows the encounters more closely, with room for their pleasures and unfinished possibilities.</p></header><p class="status">Applied to all three canonical <strong>final.md</strong> chapters. All 19 encounter anchors and all placements remain. Supporting drafts informed the revision; their earlier versions and exact changes are preserved. No new artifact or runtime test is claimed.</p><nav>'+nav+'<a href="ARTIFACT_DEVELOPMENT.md">Next: Boolean bodies and spaces</a><a href="DECISIONS.md">Decisions and source checks</a><a href="changes.json">All edited files</a></nav><div id="reading"></div>'+''.join(parts)+'<footer><p>This is a reading and companion-text pass. The burrow’s earlier bounded desktop route evidence remains in <a href="../2026-09-20-boolean-review/SUMMARY.md">the 20 September record</a>. It is not a new headset test. Maps, implementation and sequence order were preserved.</p></footer></main></body></html>'
(O/'index.html').write_text(page,encoding='utf-8')
print('Built the three current chapters with complete before/after comparisons.')
